import {deduplicateJobs} from './opportunity-tools.mjs?v=153';
import {qualificationFit} from './qualification-fit.mjs?v=148';
import {filterRoleAlignedJobs,resumeRoleIntent,roleAlignment} from './role-alignment.mjs?v=153';
import {readManualJobs} from './platform-jobs.mjs?v=136';
import {recommendationExperience} from './experience-policy.mjs?v=153';
import {matchesPreferredCities} from './locations.mjs?v=153';
import {extract} from './resume-tools.mjs?v=113';
const norm=s=>String(s||'').toLowerCase().match(/[a-z][a-z0-9+#.-]{1,}/g)||[];
export function lexicalScore(query,text){const q=[...new Set(norm(query))],t=new Set(norm(text));return q.length?q.filter(w=>t.has(w)).length/q.length:0;}
export function validatePublicFeed(data,now=Date.now()/1000){if(data?.format!=='nextrole-public-jobs'||data.version!==1||!Array.isArray(data.jobs)||data.jobs.length>30000)throw Error('Invalid public job feed.');return data.jobs.filter(j=>{try{const u=new URL(j.url);return u.protocol==='https:'&&!u.username&&!u.password&&typeof j.id==='string'&&typeof j.company==='string'&&typeof j.title==='string'&&typeof j.location==='string'&&typeof j.description==='string'&&j.description.length<=80000&&Number.isFinite(j.last_checked)&&j.last_checked<=now+300&&j.last_checked>=now-(String(j.source||'').startsWith('platform:')?86400:7*86400)&&/\b(?:India|Secunderabad|Cyberabad|Thane|Panvel|Pimpri|Chinchwad|Whitefield|Hosur|Tambaram|Sriperumbudur|Mohali|Panchkula|Kakkanad|Bengaluru|Bangalore|Hyderabad|Pune|Chennai|Mumbai|Bombay|Gurugram|Gurgaon|Noida|New Delhi|Kolkata|Calcutta|Kochi|Cochin|Thiruvananthapuram|Trivandrum|Ahmedabad|Chandigarh|Coimbatore|Indore|Jaipur|Bhubaneswar|worldwide|anywhere in the world)\b/i.test(j.location);}catch{return false;}});}
export function titleExperienceFit(title,years){const m=String(title||'').match(/\b(\d+(?:\.\d+)?)\s*(?:[-–—]\s*(\d+(?:\.\d+)?)|\+)?\s*(?:years?|yrs?)\b/i);return !m||Number(years)>=Number(m[1]);}
export function filterPublicJobs(jobs,p){return jobs.filter(j=>recommendationExperience(j,p.experience)&&titleExperienceFit(j.title,p.experience)&&matchesPreferredCities(j.location,p.cities||[],p.workstyle==='Remote',p.include_nearby)&&(p.workstyle==='any'||j.style===p.workstyle));}
let feed=null,lastFeedRead=0,pending=null,worker=null,requests=new Map(),next=0;
export async function loadPublicFeed(refresh=false){if(feed&&!refresh&&Date.now()-lastFeedRead<300000)return feed;if(pending)return pending;pending=(async()=>{const urls=['https://raw.githubusercontent.com/H-ana/NextRole/main/nextrole/dist/public-jobs.json',new URL('./public-jobs.json',import.meta.url).href];const reads=await Promise.allSettled(urls.map(async url=>{const r=await fetch(url,{cache:refresh?'reload':'default',signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('Feed unavailable');const text=await r.text();if(text.length>80000000)throw Error('Feed too large');const data=JSON.parse(text);data.jobs=validatePublicFeed(data);return data;}));const valid=reads.filter(r=>r.status==='fulfilled').map(r=>r.value);if(!valid.length)throw Error('The public company feed could not be loaded. Try again shortly.');const primary=valid[0],fallback=valid[1];if(fallback){const checked=new Map((primary.sources||[]).map(s=>[s.id,s.last_success||0])),byId=new Map(primary.jobs.map(j=>[j.id,j]));for(const j of fallback.jobs)if((checked.get(j.source)||0)<j.last_checked&&(!byId.has(j.id)||byId.get(j.id).last_checked<j.last_checked))byId.set(j.id,j);primary.jobs=[...byId.values()];primary.generated_at=Math.max(primary.generated_at||0,fallback.generated_at||0);}primary.jobs=deduplicateJobs(primary.jobs);feed=primary;lastFeedRead=Date.now();return feed;})().finally(()=>pending=null);return pending;}

function semantic(query,jobs,progress){if(!worker){worker=new Worker(new URL('./semantic-worker.mjs?v=125',import.meta.url),{type:'module'});worker.onmessage=e=>{const task=requests.get(e.data.id);if(!task)return;if(e.data.progress){task.progress(e.data.progress);return;}requests.delete(e.data.id);clearTimeout(task.timer);e.data.error?task.reject(Error(e.data.error)):task.resolve(e.data.scores);};worker.onerror=()=>{for(const task of requests.values()){clearTimeout(task.timer);task.reject(Error('Local semantic model unavailable.'));}requests.clear();worker?.terminate();worker=null;};}return new Promise((resolve,reject)=>{const id=++next,timer=setTimeout(()=>{requests.delete(id);worker?.terminate();worker=null;reject(Error('Local semantic matching timed out.'));},240000);requests.set(id,{resolve,reject,progress,timer});worker.postMessage({id,query,jobs:jobs.map(j=>j.title+'\n'+j.description.slice(0,12000))});});}
export async function searchPublicJobs(resume,preferences,{refresh=false,useSemantic=false,progress=()=>{}}={}){let data;try{data=await loadPublicFeed(refresh);}catch(error){const manual=readManualJobs(globalThis.localStorage);if(!manual.length)throw error;data={jobs:[],generated_at:Date.now()/1000,manual_only:true};}let jobs=filterRoleAlignedJobs(filterPublicJobs(deduplicateJobs([...readManualJobs(globalThis.localStorage),...data.jobs]),preferences),resume,preferences),query=resume+'\n'+(preferences.target_roles||'');const roleIntent=resumeRoleIntent(resume,preferences.target_roles);// Qualification gaps inform review; they do not suppress role-aligned partial matches.
jobs=jobs.map(j=>({...j,experience_group:recommendationExperience(j,preferences.experience).group,qualification_fit:qualificationFit(j,resume)}));jobs=jobs.map(j=>({...j,role_alignment:roleAlignment(j,roleIntent),skills:extract(j.description).skills,relevance_score:Math.round(lexicalScore(query,j.title+' '+j.description)*100),ranking_method:'local-keywords-v1'}));jobs.sort((a,b)=>b.relevance_score-a.relevance_score);let method='lexical',note='';if(useSemantic&&resume.trim()&&jobs.length){const count=Math.min(250,jobs.length);try{progress('Comparing your resume with jobs…');const scores=await semantic(query,jobs.slice(0,count),progress);jobs=jobs.map((j,i)=>i<count?({...j,relevance_score:Math.round(Math.max(0,Math.min(1,scores[i]))*80+j.relevance_score*.2),semantic_score:scores[i],ranking_method:'browser-semantic-v1'}):j);jobs.sort((a,b)=>b.relevance_score-a.relevance_score);method='semantic';note=count<data.jobs.length?'Local semantic ranking reviews up to 250 filtered candidates.':'';}catch{note='The local model could not run. Keyword ranking is shown instead.';}}const confirmed=jobs.filter(j=>j.experience_group==='confirmed'),unknown=jobs.filter(j=>j.experience_group==='unknown');return {jobs:[...confirmed.slice(0,200),...unknown.slice(0,100)],experience_not_specified_count:unknown.length,confirmed_experience_count:confirmed.length,eligible_count:jobs.length,ranking_mode:method,resume_ranked:!!resume.trim(),feed_updated:data.generated_at,manual_only:!!data.manual_only,feed_note:note};}
export function stopSemantic(){worker?.terminate();worker=null;for(const t of requests.values()){clearTimeout(t.timer);t.reject(Error('Matching cancelled.'));}requests.clear();}
